import { FC } from 'react';
import OptumLoader from './optum';
import OptumDataCoreLoader from './optum-data-core';
import { DefaultLoader } from './default-loader';
import { WriteBackLoaderProps } from './type';

const loadersMap: Record<string, FC> = {
  optum: OptumLoader,
  optumDataCore: OptumDataCoreLoader,
};

export const calcWriteBackLoaderForApp = (appId?: string): FC<WriteBackLoaderProps> => {
  if (appId && loadersMap[appId]) {
    return loadersMap[appId];
  }

  return DefaultLoader;
};
